figure.sourcecode:
{
  "namespace": {
    "saref": "https://saref.etsi.org/core/"
  },
  "sdfThing": {
    "Room001": {
      "description": "Contains lightbulb and thermostat",
      "sdfObject": {
        "lightbulb": {
          "description": "A smart lightbulb",
          "sdfProperty": {
            "adjacent-node": {
              "type": "object",
              "sdfType": "link",
              "sdfProtocolMap": {
                "ble": {
                  "serviceID": "361c9c4f-22d7-4a1e-824b-8b61045a566a",
                  "characteristicID": "b7adf665-37c7-44be-8e1c-651a10573613"
                }
              }
            }
          },
          "sdfRelation": {
            "sameRoomAsThermostat": {
              "relType": "saref:isLocatedIn",
              "target": "#/sdfThing/Room001/sdfObject/thermostat",
              "description": "This lightbulb is located in the same room as the thermostat.",
              "label": "Located together"
            }
          }
        },
        "thermostat": {
          "description": "A thermostat is in the same room as the lightbulb",
          "sdfProperty": {
            "adjacent-node": {
              "type": "object",
              "sdfType": "link"
            }
          }
        }
      }
    }
  }
}

{
  "namespace": {
    "exrel": "https://example.com/sdf-relations#"
  },
  "sdfThing": {
    "boat007": {
      "label": "Boat #007",
      "description": "Digital twin of a vessel with heater and battery subsystems",
      "sdfContext": {
        "vesselId": { "type": "string", "const": "boat007" },
        "homePort": { "type": "string", "const": "port007" }
      },
      "sdfObject": {
        "heater1": {
          "sdfProperty": {
            "status": { "type": "boolean" },
            "temperature": { "type": "number", "unit": "Cel" }
          },
          "sdfAction": {
            "turnOn": { "description": "Activate the heater" },
            "turnOff": { "description": "Deactivate the heater" }
          },
          "sdfContext": {
            "manufacturer": { "type": "string", "const": "HeaterTech Inc." },
            "model": { "type": "string", "const": "HEATER-2025-V1" }
          },
          "sdfRelation": {
            "temperatureControl": {
              "target": "#/sdfThing/boat007/sdfObject/thermostat1",
              "relType": "exrel:regulatedBy"
            }
          }
        },
        "thermostat1": {
          "sdfProperty": {
            "setPoint": { "type": "number", "unit": "Cel" },
            "mode": { "type": "string" }
          }
        },
        "batterySensor1": {
          "sdfProperty": {
            "chargeLevel": { "type": "number", "unit": "percent" },
            "voltage": { "type": "number", "unit": "V" }
          },
          "sdfRelation": {
            "batteryToController": {
              "target": "#/sdfThing/boat007/sdfObject/powerController1",
              "relType": "exrel:connectedTo"
            }
          }
        },
        "powerController1": {
          "sdfAction": {
            "connect": { "description": "Connect battery power" },
            "disconnect": { "description": "Disconnect battery power" }
          }
        }
      }
    }
  }
}

{
  "namespace": {
    "exrel": "https://example.com/sdf-relations#"
  },
  "sdfThing": {
    "patientMonitor001": {
      "sdfContext": {
        "wardLocation": { "type": "string", "const": "ICU-5A" },
        "patientID": { "type": "string", "const": "PT123456" },
        "manufacturer": { "type": "string", "const": "MediTech" },
        "model": { "type": "string", "const": "IM-500" },
        "serialNumber": { "type": "string", "const": "MT-IM500-00789" }
      },
      "sdfObject": {
        "ecg": {
          "sdfProperty": {
            "heartRate": { "type": "number", "unit": "1/min" },
            "rhythmType": { "type": "string" }
          },
          "sdfRelation": {
            "monitoredByAlertSystem": {
              "target": "#/sdfThing/patientMonitor001/sdfObject/alertSystem",
              "relType": "exrel:monitoredBy"
            }
          }
        },
        "infusionPump": {
          "sdfProperty": {
            "flowRate": { "type": "number", "unit": "mL/h" },
            "volumeRemaining": { "type": "number", "unit": "mL" }
          }
        },
        "alertSystem": {
          "sdfEvent": {
            "highHeartRateAlert": {
              "description": "Raised when the monitoring application detects a high heart rate"
            }
          }
        }
      }
    }
  }
}

{
  "namespace": {
    "exrel": "https://example.com/sdf-relations#"
  },
  "sdfThing": {
    "building001": {
      "description": "Digital twin of a heterogeneous smart building",

      "sdfContext": {
        "buildingUse": {
          "type": "string",
          "const": "office"
        }
      },

      "sdfObject": {

        "room101": {
          "sdfContext": {
            "roomNumber": {
              "type": "string",
              "const": "101"
            },
            "floor": {
              "type": "integer",
              "const": 1
            },
            "zone": {
              "type": "string",
              "const": "eastWing"
            }
          }
        },

        "lightingSystem": {
          "description": "Lighting system implemented with Matter",
          "sdfProperty": {
            "powerState": {
              "type": "boolean"
            },
            "brightness": {
              "type": "integer",
              "unit": "percent"
            }
          },
          "sdfAction": {
            "setBrightness": {
              "sdfInputData": {
                "type": "integer",
                "unit": "percent"
              }
            }
          },
          "sdfRelation": {
            "installedInRoom": {
              "target": "#/sdfThing/building001/sdfObject/room101",
              "relType": "exrel:locatedIn"
            }
          }
        },

        "hvacSystem": {
          "description": "HVAC system implemented with BACnet",
          "sdfProperty": {
            "temperatureSetPoint": {
              "type": "number",
              "unit": "Cel"
            },
            "operatingMode": {
              "type": "string"
            }
          },
          "sdfAction": {
            "setTemperature": {
              "sdfInputData": {
                "type": "number",
                "unit": "Cel"
              }
            }
          },
          "sdfRelation": {
            "controlsRoom": {
              "target": "#/sdfThing/building001/sdfObject/room101",
              "relType": "exrel:controlsClimateOf"
            }
          }
        },

        "shadingSystem": {
          "description": "Shading system implemented with KNX",
          "sdfProperty": {
            "blindPosition": {
              "type": "integer",
              "unit": "percent",
              "minimum": 0,
              "maximum": 100,
              "description": "Current blind position"
            }
          },
          "sdfAction": {
            "setBlindPosition": {
              "description": "Sets the blind position",
              "sdfInputData": {
                "type": "integer",
                "unit": "percent",
                "minimum": 0,
                "maximum": 100
              }
            }
          },
          "sdfRelation": {
            "installedInRoom": {
              "target": "#/sdfThing/building001/sdfObject/room101",
              "relType": "exrel:locatedIn"
            }
          }
        },

        "environmentSensor": {
          "description": "Environmental sensor implemented with CoAP",
          "sdfProperty": {
            "temperature": {
              "type": "number",
              "unit": "Cel"
            },
            "co2Concentration": {
              "type": "number",
              "unit": "ppm"
            }
          },
          "sdfRelation": {
            "sensorLocation": {
              "target": "#/sdfThing/building001/sdfObject/room101",
              "relType": "exrel:locatedIn"
            }
          }
        },

        "energyMeter": {
          "description": "Energy meter implemented with MQTT",
          "sdfProperty": {
            "powerConsumption": {
              "type": "number",
              "unit": "W"
            }
          },
          "sdfRelation": {
            "measuresHVAC": {
              "target": "#/sdfThing/building001/sdfObject/hvacSystem",
              "relType": "exrel:measuresPowerOf"
            }
          }
        }

      }
    }
  }
}

{
  "namespace": {
    "exrel": "https://example.com/sdf-relations#"
  },
  "sdfThing": {
    "smartNetwork001": {
      "description": "Digital twin system for abnormal-situation prediction and response",
      "sdfObject": {
        "networkDeviceTwin": {
          "sdfContext": {
            "deviceId": { "type": "string", "const": "network-device-001" }
          },
          "sdfProperty": {
            "operationalState": { "type": "string" },
            "utilization": { "type": "number", "unit": "percent" },
            "latency": { "type": "number", "unit": "ms" }
          }
        },
        "trafficTwin": {
          "sdfProperty": {
            "currentTraffic": { "type": "number", "unit": "Mbit/s" },
            "packetRate": { "type": "number", "unit": "1/s" },
            "anomalyScore": { "type": "number", "minimum": 0, "maximum": 1 }
          },
          "sdfData": {
            "trafficHistory": { "type": "array" },
            "trafficPattern": { "type": "string" }
          },
          "sdfEvent": {
            "abnormalSituationPredicted": {
              "description": "Indicates that the analytics function predicts an abnormal situation"
            }
          },
          "sdfAction": {
            "applyCountermeasure": {
              "description": "Applies a countermeasure selected by an application",
              "sdfInputData": {
                "type": "object",
                "properties": {
                  "countermeasureId": { "type": "string" }
                }
              }
            }
          },
          "sdfRelation": {
            "associatedNetworkDevice": {
              "target": "#/sdfThing/smartNetwork001/sdfObject/networkDeviceTwin",
              "relType": "exrel:associatedWith"
            }
          }
        }
      }
    }
  }
}

li.t:
receiving information about digital twins of the same observable object
that exist in other domains in which the observable object performs
different roles;

configuring the observable object as a digital twin based on the
collected data, defined purpose, and role of the observable object
in the domain;
